### **🐱 Cat Café API v1.0**  
*(Copy/paste this into a file named `cat_cafe_api.py` and run with `python cat_cafe_api.py`)*  

```python
from flask import Flask, jsonify, request
import random

app = Flask(__name__)

# Mock Database
users = {"cat_lover_42": {"name": "Alice", "points": 10}}
cats_db = {
    "sir_whiskers": {
        "name": "Sir Whiskers",
        "bio": "Knocks over cups for science.",
        "adopted": False,
        "image": "https://placekitten.com/200/300"
    },
    "lady_meow": {
        "name": "Lady Meow",
        "bio": "Demands treats in iambic pentameter.",
        "adopted": False,
        "image": "https://placekitten.com/200/301"
    }
}

# Endpoints
@app.route('/')
def home():
    return jsonify({"message": "Welcome to Purr-allel Universe Café API! 🐾"})

@app.route('/api/cat_gif')
def cat_gif():
    moods = ["playful", "sleepy", "chaotic", "judgmental"]
    return jsonify({
        "gif": f"https://placekitten.com/400/400?mood={random.choice(moods)}",
        "alt_text": "Random cat GIF"
    })

@app.route('/api/adoptable_cats')
def adoptable_cats():
    available_cats = [cat for cat in cats_db.values() if not cat["adopted"]]
    return jsonify({"cats": available_cats})

@app.route('/api/adopt/<cat_name>', methods=['POST'])
def adopt_cat(cat_name):
    if cat_name.lower() not in cats_db:
        return jsonify({"error": "Cat not found. Did you check the nap room?"}), 404
    if cats_db[cat_name.lower()]["adopted"]:
        return jsonify({"error": "This cat has already found a home! 🏡"}), 400

    cats_db[cat_name.lower()]["adopted"] = True
    user_id = request.headers.get("X-User-ID")
    users[user_id]["points"] += 5  # Loyalty points

    return jsonify({
        "success": f"Congrats! You adopted {cat_name}!",
        "next_steps": [
            "Sign the 'Paw-tron' contract",
            "Pay the tuna tax (optional)"
        ],
        "points": users[user_id]["points"]
    })

@app.route('/api/order', methods=['POST'])
def submit_order():
    data = request.json
    return jsonify({
        "order_id": f"MEOW-{random.randint(1000, 9999)}",
        "message": "Order received! Delivery via cat courier.",
        "estimated_time": f"{random.randint(5, 30)} minutes",
        "note": "Tip in treats appreciated."
    })

# Error Handling
@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "404: Nap in progress. Try again later."}), 404

if __name__ == '__main__':
    app.run(debug=True, port=5000)
```

